WITH deduped AS (SELECT * FROM store_sales QUALIFY ROW_NUMBER() OVER (PARTITION BY store_id ORDER BY sale_date DESC, id) = 1) SELECT CASE WHEN revenue >= 3600 THEN 'HIGH' ELSE 'LOW' END AS revenue_tier, DATE_TRUNC('MONTH', sale_date) AS activity_month, BIT_AND(units) AS units_bit_and, PERCENTILE_APPROX(revenue, ARRAY(0.25, 0.5, 0.75)) AS revenue_quartiles, ROUND(AVG(revenue), 2) AS avg_revenue FROM deduped GROUP BY GROUPING SETS ((CASE WHEN revenue >= 3600 THEN 'HIGH' ELSE 'LOW' END, DATE_TRUNC('MONTH', sale_date)), (CASE WHEN revenue >= 3600 THEN 'HIGH' ELSE 'LOW' END)) ORDER BY revenue_tier DESC
